window.__saqPaperQuestions("2018-2-pah",[{"number":1,"title":"","stemText":"A 3 year old boy has been brought to the ED by ambulance. He has been unwell with fever and\nvomiting for 2 days. He has developed lethargy and a rash this morning.\nThe child is unvaccinated. A clinical photograph has been provided in the PROPS BOOKLET.","parts":[{"id":"a","label":"Part A","prompt":"List 3 descriptive features from the photo. (3 marks)\n1)________________________________________________________________________________ 2)________________________________________________________________________________ 3)________________________________________________________________________________ Your initial assessment suggests bacterial infection as the most likely cause of the presentation."},{"id":"b","label":"Part B","prompt":"List 4 of the most likely bacterial pathogens that could cause this presentation. (4 marks) 1)________________________________________________________________________________ 2)________________________________________________________________________________ 3)________________________________________________________________________________ 4)________________________________________________________________________________"},{"id":"c","label":"Part C","prompt":"Other than bacterial infection, list 3 differential diagnoses for this presentation. (3 marks) 1)________________________________________________________________________________ 2)________________________________________________________________________________ 3)________________________________________________________________________________ The patient’s initial vital signs are: AVPU responds to voice Pulse 180 /min\n\nBP\n80/35 mmHg Temperature 34.5 degrees O2 sats 98% room air Your clinical assessment is consistent with septic shock."},{"id":"d","label":"Part D","prompt":"Other than coagulation studies, list your 3 most important initial investigations, including justification. (3 marks) Investigation Justification"},{"id":"e","label":"Part E","prompt":"State the details of your 2 most important initial treatment steps. (2 marks)\n1)________________________________________________________________________________ 2)________________________________________________________________________________ The patient stabilises after your initial management. One of your laboratory tests is provided in the PROPS BOOKLET."},{"id":"f","label":"Part F","prompt":"Interpret the results. (1 mark)"},{"id":"g","label":"Part G","prompt":"List 4 other potential complications of this patient’s presentation. (4 marks)\n1)________________________________________________________________________________ 2)________________________________________________________________________________ 3)________________________________________________________________________________ 4)________________________________________________________________________________"}],"propPages":["asset:img7767fd69de2615ee39","asset:img2d26a30aa701ef9fb3"],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">Drug reaction / SJS</div><div class=\"answer-line\">Thrombocytopenia from any cause</div><div class=\"answer-line\">Viral eg CMV</div><div class=\"answer-line\">DIC any cause eg malignancy</div><div class=\"answer-line\">Autoimmune causes – SLE</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">Blood culture – before Abs to guide future Rx</div><div class=\"answer-line\">BSL – manage hypoglycaemia common in overwhelming sepsis</div><div class=\"answer-line\">VBG – define severity of illness – met acidosis, lactate</div><div class=\"answer-line\"><strong>5 </strong></div><div class=\"answer-line\">IV abs – cefotaxime or <strong>ceftriaxone 50mg/kg,</strong> vancomycin 30mg/kg, +/- fluclox +/- gent</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">Acute renal failure</div></section><section class=\"answer-part\"><h5>Part D</h5><div class=\"answer-line\">Drug reaction / SJS</div><div class=\"answer-line\">Thrombocytopenia from any cause</div><div class=\"answer-line\">Viral eg CMV</div><div class=\"answer-line\">DIC any cause eg malignancy</div><div class=\"answer-line\">Autoimmune causes – SLE</div></section><section class=\"answer-part\"><h5>Part E</h5><div class=\"answer-line\">Blood culture – before Abs to guide future Rx</div><div class=\"answer-line\">BSL – manage hypoglycaemia common in overwhelming sepsis</div><div class=\"answer-line\">VBG – define severity of illness – met acidosis, lactate</div></section><section class=\"answer-part\"><h5>Part F</h5><div class=\"answer-line\"><strong>5 </strong></div><div class=\"answer-line\">IV abs – cefotaxime or <strong>ceftriaxone 50mg/kg,</strong> vancomycin 30mg/kg, +/- fluclox +/- gent</div><div class=\"answer-line\">IV normal saline 20ml/kg bolus</div></section><section class=\"answer-part\"><h5>Part G</h5><div class=\"answer-line\"><strong>6</strong></div><div class=\"answer-line\">Disseminated intravascular coagulation</div><div class=\"answer-line\"><strong>7 </strong></div><div class=\"answer-line\">death</div><div class=\"answer-line\">Acute renal failure</div><div class=\"answer-line\">Ischaemic hepatitis / brain injury</div><div class=\"answer-line\">Amputation limbs</div><div class=\"answer-line\">Lots of stuff OK</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":2,"title":"","stemText":"A 45 year old man has presented with a painful, red, swollen left testicle. The pain began as a mild ache 7 days ago and has been gradually increasing to the point where it is now severe. He has had fevers and chills for the last 2 days. On examination, he has a red, swollen left side of the scrotum with an enlarged and diffusely tender left testicle.","parts":[{"id":"a","label":"Part A","prompt":"List 4 investigations you would perform. Justify your use of these tests. (4 marks)"},{"id":"b","label":"Part B","prompt":"State the most likely diagnosis. (1 mark) Your clinical assessment confirms this diagnosis."},{"id":"c","label":"Part C","prompt":"List 4 indications for inpatient admission you would seek to exclude in this man. (4 marks) 1)________________________________________________________________________________ 2)________________________________________________________________________________ 3)________________________________________________________________________________ 4)________________________________________________________________________________ You clinical assessment is that this patient can be managed safely as an outpatient."},{"id":"d","label":"Part D","prompt":"State 2 steps in your outpatient management of this man. Include drug doses where\nappropriate. (2 marks) 1)________________________________________________________________________________ 2)________________________________________________________________________________"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\"><strong>9/11</strong></div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">Oral Abs – trimethoprim 300mg nocte 1/52, ceftriaxone 500mg once IM, azithromycin 500mg oral</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">Epididymo-orchitis</div></section><section class=\"answer-part\"><h5>Part D</h5><div class=\"answer-line\"><strong>3 </strong></div><div class=\"answer-line\">Sepsis – ie unwell</div><div class=\"answer-line\">Complicated by abscess</div><div class=\"answer-line\">Co-morbidities decreasing cardiovascular reserve – eg significant CCF</div><div class=\"answer-line\">Severe pain</div><div class=\"answer-line\">Social circumstances eg homeless / unable to get follow up</div><div class=\"answer-line\">Failure outpatient management</div><div class=\"answer-line\">Analgesia – paracetamol 1q QID, ibuprofen 400mg tds</div><div class=\"answer-line\">Oral Abs – trimethoprim 300mg nocte 1/52, ceftriaxone 500mg once IM, azithromycin 500mg oral</div><div class=\"answer-line\">now and on one week</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":3,"title":"","stemText":"A 77 year old lady has presented with palpitations.\nHer ECG is provided in the PROPS BOOKLET.","parts":[{"id":"a","label":"Part A","prompt":"List the 2 most important features of this ECG. (2 marks)\n1)________________________________________________________________________________ 2)________________________________________________________________________________ On examination, she has the following vital signs:\n\nGCS\n\nBP\n115/65 mmHg O2 sats 98% room air Temperature 36.5 degrees"},{"id":"b","label":"Part B","prompt":"List 5 drugs you might use in the management of this patient’s problem. Include initial\ndoses. For each drug, state the clinical circumstances appropriate for its use. (10 marks) Drug / dose Clinical circumstances"}],"propPages":["asset:img161affb49c58d571d0"],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">Metoprolol 25mg po or 2.5mg boluses up to 15mg IV – has normal BP, minimal/no CCF, no C/I such</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><thead><tr><th>Item</th><th>Response / justification</th></tr></thead><tbody><tr><td>hypotension and current CCF, avoid if co-prescribed beta blocker</td><td>Digoxin 500mcg slow infusion – use for rate control when low BP or presence of CCF, slow onset</td></tr><tr><td>action</td><td>Flecainide 2mg/kg oral / IV – for cardioversion – structurally normal heart when AF is less than 48hr</td></tr><tr><td>onset</td><td>Amiodarone 5mg/kg slow IV – for cardioversion – when flecainide C/I and lees than 48 hr onset AF</td></tr></tbody></table></div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":4,"title":"","stemText":"A 32 year old woman has presented with headache and visual changes. She is 38 weeks pregnant. You are concerned about the possibility of pre-eclampsia.","parts":[{"id":"a","label":"Part A","prompt":"List 4 examination features that would be supportive of pre-eclampsia. (4 marks)\n1)________________________________________________________________________________ 2)________________________________________________________________________________ 3)________________________________________________________________________________ 4)________________________________________________________________________________"},{"id":"b","label":"Part B","prompt":"List 4 laboratory abnormalities that would be supportive of pre-eclampsia. (4 marks)\n1)________________________________________________________________________________ 2)________________________________________________________________________________ 3)________________________________________________________________________________ 4)________________________________________________________________________________ Your clinical assessment is consistent with pre-eclampsia. The patient’s vital signs are: Pulse 100 /min\n\nBP\n160/110 mmHg O2 sats 99% room air While in the ED, the patient begins to have a seizure."},{"id":"c","label":"Part C","prompt":"List 5 components of your management of this situation. (5 marks)\n1)________________________________________________________________________________ 2)________________________________________________________________________________ 3)________________________________________________________________________________ 4)________________________________________________________________________________ 5)________________________________________________________________________________"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\"><strong>9/13 </strong></div><div class=\"answer-line\"><strong>1</strong></div><div class=\"answer-line\"><strong>Hypertension &gt;140/or &gt;90mmHg </strong></div><div class=\"answer-line\">RUQ tenderness</div><div class=\"answer-line\">Papilloedema</div><div class=\"answer-line\">Hyper-reflexia</div><div class=\"answer-line\">Peripheral oedema</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\"><strong>2 </strong></div><div class=\"answer-line\">Raised uric acid</div><div class=\"answer-line\">Acute renal failure</div><div class=\"answer-line\">Haemolysis – low HB, raised LDH</div><div class=\"answer-line\">Raised LFTs</div><div class=\"answer-line\">Low platelets</div><div class=\"answer-line\">Proteinuria</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\"><strong>3</strong></div><div class=\"answer-line\">Terminate seizure midazolam IV 2.5 – 5mg</div><div class=\"answer-line\">Left lateral position</div><div class=\"answer-line\"><strong>IV MgSO4 20mmol infusion </strong></div><div class=\"answer-line\"><strong>Urgent Obstetric attendance for delivery </strong></div><div class=\"answer-line\">BP management – eg hydralazine 5mg IV boluses</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":5,"title":"","stemText":"Your tertiary ED has received feedback that the time to thrombolysis for stroke in your centre is unacceptably long. You have been tasked to remedy this situation.","parts":[{"id":"a","label":"Part A","prompt":"List 5 possible contributory factors in the delay to thrombolysis in stroke. (5 marks)\n1)________________________________________________________________________________ 2)________________________________________________________________________________ 3)________________________________________________________________________________ 4)________________________________________________________________________________ 5)________________________________________________________________________________"},{"id":"b","label":"Part B","prompt":"State 5 solutions to the issues identified in part 1 . (5 marks)\n1)________________________________________________________________________________ 2)________________________________________________________________________________ 3)________________________________________________________________________________ 4)________________________________________________________________________________ 5)________________________________________________________________________________"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">Liaise with stroke unit to create pathway for referral / discussion</div><div class=\"answer-line\">Liaise with radiology department to improve access to CT and to ensure immediate reporting</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">Plenty of other stuff OK</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":6,"title":"","stemText":"A 44 year old woman has presented with large volume haemoptysis.","parts":[{"id":"a","label":"Part A","prompt":"List 6 investigations you might perform. Provide justification for each. (6 marks)\nInvestigation Justification The patient required intubation as part of her management. The patient’s vital signs are: Pulse 115 /min\n\nBP\n110/70 mmHg O2 sats 95%\n\nFiO2 0.7"},{"id":"b","label":"Part B","prompt":"List 3 options for definitive management of this patient’s haemoptysis. For each, give the clinical circumstances in which it would be appropriate. (6 marks) Management option Clinical circumstance"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><thead><tr><th>Investigation</th><th>Justification</th></tr></thead><tbody><tr><td>Renal function – in suspected vasculitis eg Wegeners</td><td></td></tr></tbody></table></div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><thead><tr><th>Item</th><th>Response / justification</th></tr></thead><tbody><tr><td>Thoracotomy – surgeon available, ongoing bleeding, not amenable to IR</td><td>Endoscopic – minor haemoptysis – settled</td></tr></tbody></table></div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":7,"title":"","stemText":"A 65 year old woman has presented to the ED with severe generalised abdominal pain.\nExamination reveals a generally tender and guarded abdomen.\nHer vital signs are:\n\nGCS\nPulse 120 /min\n\nBP\n95/55 mmHg O2 sats 96% room air A slice from her abdominal CT scan is provided in the PROPS BOOKLET.","parts":[{"id":"a","label":"Part A","prompt":"List 5 abnormalities in the CT scan. (5 marks)\n1)________________________________________________________________________________ 2)________________________________________________________________________________ 3)________________________________________________________________________________ 4)________________________________________________________________________________ 5)________________________________________________________________________________"},{"id":"b","label":"Part B","prompt":"What is the likely diagnosis? (1 mark)"},{"id":"c","label":"Part C","prompt":"State 4 components of your management of this patient. (4 marks)\n1)________________________________________________________________________________ 2)________________________________________________________________________________ 3)________________________________________________________________________________ 4)________________________________________________________________________________"}],"propPages":["asset:imgb8ef5750965c7e53d4"],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\"><strong>7/10 </strong></div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\"><strong>IP free fluid </strong></div><div class=\"answer-line\"><strong>IP free air </strong></div><div class=\"answer-line\">Defect anterior stomach wall</div><div class=\"answer-line\">Fat stranding around stomach</div><div class=\"answer-line\">Thick walled stomach</div><div class=\"answer-line\">Multiple small gallstones</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\"><strong>2 </strong></div><div class=\"answer-line\">Perforated peptic ulcer</div><div class=\"answer-line\"><strong>3 </strong></div><div class=\"answer-line\">IV fluid – 1L N/S stat aiming for BP&gt;100, reduction pulse rate / adequate perfusion</div><div class=\"answer-line\">Analgesia – morphine 2.5mg aliquots</div><div class=\"answer-line\"><strong>Urgent surgical attendance for laparotomy </strong></div><div class=\"answer-line\">IV Abs – something sensible – amp 1g, gent 5-7/kg, metronidazole 500mg</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":8,"title":"","stemText":"A 75 year old woman has been brought to the hospital after having a syncopal episode while at home. At the time of your initial examination, she has recovered fully, with no symptoms.","parts":[{"id":"a","label":"Part A","prompt":"List 3 causes of neurally mediated syncope. (3 marks)\n1)________________________________________________________________________________ 2)________________________________________________________________________________ 3)________________________________________________________________________________"},{"id":"b","label":"Part B","prompt":"List 3 causes of orthostatic hypotension. (3 marks)\n1)________________________________________________________________________________ 2)________________________________________________________________________________ 3)________________________________________________________________________________"},{"id":"c","label":"Part C","prompt":"List 5 ECG findings that would suggest arrhythmogenic syncope in a currently\nasymptomatic patient. (5 marks) 1)________________________________________________________________________________ 2)________________________________________________________________________________ 3)________________________________________________________________________________ 4)________________________________________________________________________________ 5)________________________________________________________________________________"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">Bifascicular block</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">Prolonged or short QT</div><div class=\"answer-line\">Brugada pattern – RBBB with ST elevation V1-3</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">Bifascicular block</div><div class=\"answer-line\">Pre-excitation (delta waves)</div><div class=\"answer-line\">Prolonged or short QT</div><div class=\"answer-line\">Brugada pattern – RBBB with ST elevation V1-3</div><div class=\"answer-line\">Findings of ARVC – epsilon waves, negative T waves right precordial leads</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":9,"title":"","stemText":"A 79 year old man has been brought to the ED after falling in the car park of his local shopping centre. He has pain in his pelvis. An x-ray of his pelvis is provided in the PROPS BOOKLET.","parts":[{"id":"a","label":"Part A","prompt":"List 3 abnormalities in the x-ray. (3 marks)\n1)________________________________________________________________________________ 2)________________________________________________________________________________ 3)________________________________________________________________________________ Three hours after arriving to the ED, the patient has become confused.\nHis vital signs are:\n\nGCS\nE4 V4 M5 Pulse 125 /min\n\nBP\n95/40 mmHg"},{"id":"b","label":"Part B","prompt":"List 5 potential causes of this patient’s deterioration. For each, state how you will assess for its presence (history, examination or investigation). (10 marks) Potential cause Assessment feature"}],"propPages":["asset:img2ebfc3dd479881dedb"],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">Right acetabular #</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><thead><tr><th>Cause</th><th>Distinguishing feature</th></tr></thead><tbody><tr><td>Drug related – overdose morphine – check drug chart</td><td>Hypoxia – O2 sats, examine chest / CXR</td></tr></tbody></table></div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":10,"title":"","stemText":"A 25 year old man has been brought to your tertiary ED after a major motor vehicle accident. He was the driver of a van that collided head-on with a sedan on a stretch of highway. The patient was retrieved by helicopter from a rural hospital where he was intubated due to a reduced level of consciousness and had a right sided intercostal catheter inserted. His initial chest x-ray is provided in the PROPS BOOKLET.","parts":[{"id":"a","label":"Part A","prompt":"List 4 pathologies demonstrated on this x-ray. Complete the table for each pathology by\nstating one supportive radiographical feature. (8 marks) Pathology Radiographical feature The initial vital signs are: Pulse 130 /min\n\nBP\n75/45 mmHg O2 sats 86% As part of your initial management, an arterial blood gas has been taken. The result is provided in the PROPS BOOKLET."},{"id":"b","label":"Part B","prompt":"List 4 abnormalities on the arterial blood gas. Give the most likely explanation for each\nabnormality. (8 marks) Abnormality Explanation"},{"id":"c","label":"Part C","prompt":"State 4 initial actions you would take based on all of the clinical information provided.\n(4 marks) 1)________________________________________________________________________________ 2)________________________________________________________________________________ 3)________________________________________________________________________________ 4)________________________________________________________________________________"},{"id":"d","label":"Part D","prompt":"List 4 measures you will take in an effort to minimise the chance of this patient developing a coagulopathy. (4 marks) 1)________________________________________________________________________________ 2)________________________________________________________________________________ 3)________________________________________________________________________________ 4)________________________________________________________________________________"}],"propPages":["asset:img4ecf7e9b6df2c3e7fb","asset:img4380324b13b806bf4e"],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><thead><tr><th>Item</th><th>Response / justification</th></tr></thead><tbody><tr><td>Normothermia / warm</td><td>Correct respiratory acidosis</td></tr></tbody></table></div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><thead><tr><th>Item</th><th>Response / justification</th></tr></thead><tbody><tr><td>Respiratory acidosis – underventilation, need to increase MV</td><td>HAGMA – mainly lactate due to tissue hypoperfusion</td></tr><tr><td>Hyperkalaemia – when corrected for acidosis is approx. 3.6</td><td>Hypoxia – due to lung pathologies V/Q mismatch – haemothorax, contusions, PTX</td></tr></tbody></table></div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\"><strong>3 </strong></div><div class=\"answer-line\">Improve pO2 – increase FiO2, increase PEEP</div><div class=\"answer-line\">Increase MV</div><div class=\"answer-line\">Give blood – O neg – aim for systolic BP &gt;80mmHg</div><div class=\"answer-line\">Insert left ICC large bore</div></section><section class=\"answer-part\"><h5>Part D</h5><div class=\"answer-line\">Normothermia / warm</div><div class=\"answer-line\">Correct respiratory acidosis</div><div class=\"answer-line\">(Restore volume is acceptable)</div><div class=\"answer-line\">Resuscitate with blood products aiming for 1:1:1 RBC:FFP:platelets</div><div class=\"answer-line\">Use ROTEM to target coagulopathy</div><div class=\"answer-line\">Normal ionised Ca</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":11,"title":"","stemText":"A 32 year old woman has been brought to the ED following one week of erratic behaviour.\nYou are concerned about the possibility of a manic episode.","parts":[{"id":"a","label":"Part A","prompt":"List 6 findings from your history or mental status examination that would be consistent\nwith mania as the cause of the patient’s behaviour. (6 marks) 1)________________________________________________________________________________ 2)________________________________________________________________________________ 3)________________________________________________________________________________ 4)________________________________________________________________________________ 5)________________________________________________________________________________ 6)________________________________________________________________________________"},{"id":"b","label":"Part B","prompt":"List 6 investigations you might perform in this patient. For each, provide justification.\n(6 marks) Investigation Justification"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\"><strong>8/12</strong></div><div class=\"answer-line\"><strong>1</strong></div><div class=\"answer-line\">Past Hx mania / bipolar AD</div><div class=\"answer-line\">Pressured speech</div><div class=\"answer-line\">Flight of ideas</div><div class=\"answer-line\">Thought derailment</div><div class=\"answer-line\">Spending money</div><div class=\"answer-line\">Sexual promiscuity</div><div class=\"answer-line\">Delusions of grandeur</div><div class=\"answer-line\">(many others)</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><thead><tr><th>Investigation</th><th>Justification</th></tr></thead><tbody><tr><td>TFTs – thyrotoxicosis can present with similar mental state</td><td>CT head – in first presentation of major mental health disorder</td></tr><tr><td>Serum Na – where excessive water consumption, cause for delirium</td><td>LP – to look to encephalitis if febrile, meningism</td></tr><tr><td>BSL – hypoglycaemia as cause for delirium, hyperglycaemia if diabetic with intercurrent illness</td><td>Urine drug screen – looking for amphetamine use as a precipitant for behavioural disturbance</td></tr><tr><td>(probably many others)</td><td></td></tr></tbody></table></div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":12,"title":"","stemText":"You are working a shift in the short stay ward of your ED. Your next patient is a 65 year old alcoholic man who was admitted overnight with vomiting of uncertain cause.","parts":[{"id":"a","label":"Part A","prompt":"List 4 conditions related to his heavy alcohol use that you might find on reviewing this\nman. For each condition, list 2 findings from your examination or investigation that would support the diagnosis. (12 marks) Condition Examination or investigation finding"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><thead><tr><th>Item</th><th>Response / justification</th></tr></thead><tbody><tr><td><strong>Acute alcohol withdrawal </strong>– tremor, tachycardia, fever, seizures</td><td><strong>Wernicke’s encephalopathy</strong> – nystagmus, confusion, ataxia</td></tr><tr><td>Peripheral neuropathy – stocking style sensory loss, loss ankle jerk</td><td>Cerebellar degeneration – dysdiadochokinesis,  nystagmus, ataxia, past pointing etc</td></tr></tbody></table></div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":13,"title":"","stemText":"A 45 year old man has presented to the ED with right eye pain after an injury at work where he was hammering metal. A clinical photograph of his right eye is provided in the PROPS BOOKLET.","parts":[{"id":"a","label":"Part A","prompt":"List 4 abnormalities in the clinical photograph. (4 marks)\n1)________________________________________________________________________________ 2)________________________________________________________________________________ 3)________________________________________________________________________________ 4)________________________________________________________________________________"},{"id":"b","label":"Part B","prompt":"Give your clinical interpretation of the information provided. (1 mark)"},{"id":"c","label":"Part C","prompt":"State 5 steps in your management of this patient. (5 marks)\n1)________________________________________________________________________________ 2)________________________________________________________________________________ 3)________________________________________________________________________________ 4)________________________________________________________________________________ 5)________________________________________________________________________________"}],"propPages":["asset:img5153145933cbac7d19"],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\"><strong>7/10 </strong></div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">Extruded iris / aqueous humour</div><div class=\"answer-line\">Irregular pupil</div><div class=\"answer-line\">Cloudy cornea</div><div class=\"answer-line\">Scleral injection</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\"><strong>2 </strong></div><div class=\"answer-line\">Penetrating eye injury</div><div class=\"answer-line\"><strong>3 </strong></div><div class=\"answer-line\">Analgesia – eg IV morphine 2.5mg aliquots</div><div class=\"answer-line\">Anti-emetic IV ondansetron 8mg</div><div class=\"answer-line\"><strong>Urgent review Ophthalmology </strong></div><div class=\"answer-line\">IV Antibiotics – drugs not required for this one</div><div class=\"answer-line\">Eye shield</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":14,"title":"","stemText":"A 12 day old boy has been brought to the ED by his mother. She has noticed a swelling in the right scrotum this morning while changing the child’s nappy.","parts":[{"id":"a","label":"Part A","prompt":"List 3 differential diagnoses. For each, list 2 cardinal examination features and the main principle in management. (12 marks) Differential diagnosis Examination features Management"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><thead><tr><th>Item</th><th>Response / justification</th></tr></thead><tbody><tr><td>Indirect inguinal hernia – extends from inguinal canal (can’t get above it), may contain bowel sounds</td><td>– urgent surgery if incarcerated, semi-urgent if reducible</td></tr><tr><td>Hydrocele – transillumination,  soft, non-tender swelling, normal testis – conservative, most resolve</td><td>by age 2</td></tr><tr><td>Testicular torsion – irritable child, tender testicle, high riding, no cremasteric reflex – urgent surgical</td><td>correction</td></tr></tbody></table></div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":15,"title":"","stemText":"A 45 year old woman has presented to the ED with confusion.\nShe has a history of primary biliary cirrhosis with chronic liver disease. Her medications include: frusemide 40mg bd, spironolactone 25md od and propranolol 40mg bd.","parts":[{"id":"a","label":"Part A","prompt":"List 6 investigations you might use to elucidate the cause of this patient’s confusion.\nProvide justification for each of your choices. (12 marks) Investigation Justification"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><thead><tr><th>Investigation</th><th>Justification</th></tr></thead><tbody><tr><td><strong>BSL</strong> – exclude hypoglycaemia as a cause in fulminant liver failure</td><td>Serum Na – hypoNa cause of confusion – due to CLD, diuretics</td></tr><tr><td>CT head – high chance of intracerebral bleed in coagulopathy due to CLD</td><td>Ascitic fluid tap – to exclude SBP as a precipitant for hepatic encephalopathy</td></tr><tr><td>Hb – GI bleed as cause for hepatic encephalopathy</td><td>One other tests for sepsis OK – CXR / urine</td></tr><tr><td>Serum NH4 – to confirm hepatic encephalopathy as a cause for confusion</td><td></td></tr></tbody></table></div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":16,"title":"","stemText":"A 47 year old father was enjoying his daughter’s birthday at a trampoline park when he fell awkwardly on to his right knee. He is complaining of right hip pain. His pelvic x-ray is provided in the PROPS BOOKLET.","parts":[{"id":"a","label":"Part A","prompt":"State the main pathology demonstrated. (1 mark)"},{"id":"b","label":"Part B","prompt":"List 2 imaging modalities that could be used to identify associated complications of this\ninjury. List 2 complicating injuries you would seek for each modality. (6 marks)\nImaging modality Associated injury"},{"id":"c","label":"Part C","prompt":"You elect to provide urgent management of this injury in the ED. State 4 biomechanical principles in your management of the injury. (4 marks) 1)________________________________________________________________________________ 2)________________________________________________________________________________ 3)________________________________________________________________________________ 4)________________________________________________________________________________"}],"propPages":["asset:img0371bc5e79973badd1"],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">Right posterior hip dislocation</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><thead><tr><th>Item</th><th>Response / justification</th></tr></thead><tbody><tr><td>Right posterior hip dislocation</td><td></td></tr></tbody></table></div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">Sedate well</div><div class=\"answer-line\">Stabilise pelvis</div><div class=\"answer-line\">Hip flexed and adducted</div><div class=\"answer-line\">Traction in this position</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":17,"title":"","stemText":"A 67 year old woman has presented to the ED after a cardiac arrest at home. She was seated on the couch watching television when she suddenly complained of chest pain, became blue and stopped breathing. Upon arrival of the ambulance service, she was unresponsive with pulseless electrical activity. Standard advanced life support resulted in a return of spontaneous circulation. On arrival to the ED, an ECG has been performed. It is provided in the PROPS BOOKLET.","parts":[{"id":"a","label":"Part A","prompt":"List 5 abnormalities on the ECG. (5 marks)\n1)________________________________________________________________________________ 2)________________________________________________________________________________ 3)________________________________________________________________________________ 4)________________________________________________________________________________ 5)________________________________________________________________________________"},{"id":"b","label":"Part B","prompt":"What is the most likely diagnosis? (1 mark)"},{"id":"c","label":"Part C","prompt":"List 4 findings you might expect to find on bedside ultrasound that would support the\ndiagnosis in Q2. (4 marks) 1)________________________________________________________________________________ 2)________________________________________________________________________________ 3)________________________________________________________________________________ 4)________________________________________________________________________________"}],"propPages":["asset:imgb408c6cee5516d8865"],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">Pulmonary embolus</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">Hyperdynamic LV</div><div class=\"answer-line\">Dilated IVC</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">Pulmonary embolus</div><div class=\"answer-line\"><strong>3</strong></div><div class=\"answer-line\">Dilated RV</div><div class=\"answer-line\">Poorly contractile RV</div><div class=\"answer-line\">Hyperdynamic LV</div><div class=\"answer-line\">Dilated IVC</div><div class=\"answer-line\">Also accept – McConnell sign (RV RWMA sparing RV apex), bowing septum to LV</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":18,"title":"","stemText":"A 65 year old man has presented to the ED with a red, swollen right knee.\nYour provisional diagnosis is gout.","parts":[{"id":"a","label":"Part A","prompt":"List 5 risk factors for gout. (5 marks)\n1)________________________________________________________________________________ 2)________________________________________________________________________________ 3)________________________________________________________________________________ 4)________________________________________________________________________________ 5)________________________________________________________________________________"},{"id":"b","label":"Part B","prompt":"List 3 findings that you would expect on joint aspiration that would be consistent with\ngout. (3 marks) 1)________________________________________________________________________________ 2)________________________________________________________________________________ 3)________________________________________________________________________________"},{"id":"c","label":"Part C","prompt":"List 3 treatment options for acute gout. Include doses. (3 marks)\n1)________________________________________________________________________________ 2)________________________________________________________________________________ 3)________________________________________________________________________________"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">Family Hx</div><div class=\"answer-line\">Diuretics – thiazide, loop</div><div class=\"answer-line\">Dietary – high purine foods, alcohol</div><div class=\"answer-line\">Hyperuricaemia</div><div class=\"answer-line\"><strong>2</strong></div><div class=\"answer-line\">Negatively bi-refringent crystals</div><div class=\"answer-line\">WBC 200 – 50000/uL</div><div class=\"answer-line\">Predom PMNs</div><div class=\"answer-line\">Yellow, turbid fluid</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">NSAIDs – eg ibuprofen 400mg tds</div><div class=\"answer-line\">Prednisone 50mg od 3 days</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">NSAIDs – eg ibuprofen 400mg tds</div><div class=\"answer-line\">Prednisone 50mg od 3 days</div><div class=\"answer-line\">Colchicine 500mcg – many different regimes exist – as long as it is safe</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":19,"title":"","stemText":"A 3 year old girl has been brought to the ED by her parents with cough and fever for 3 days. The child has become increasingly lethargic. Your assessment is consistent with severe community acquired pneumonia requiring urgent intubation. There are no obvious anatomical factors that would complicate intubation. The child’s vital signs are: Temperature 39.5 degrees Pulse 170 /min\n\nBP\n65/40 mmHg\n\nRR\n/min O2 saturation 85% 6L O2 via Hudson mask\n\nWeight\nkg","parts":[{"id":"a","label":"Part A","prompt":"List 2 main difficulties you will encounter in safely intubating this patient. For each,\nprovide 3 strategies you will employ to manage the difficulty. (8 marks)\nDifficulty Strategies"},{"id":"b","label":"Part B","prompt":"List your initial ventilator settings. (4 marks) Tidal volume (mL) Respiratory Rate (/min)\n\nFiO2 (%)\nInspiratory Pressure Limit (cm H20)"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><thead><tr><th>Item</th><th>Response / justification</th></tr></thead><tbody><tr><td>TV</td><td>90mL</td></tr><tr><td>RR</td><td></td></tr></tbody></table></div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><tbody><tr><td colspan=\"2\">Hypotension</td></tr><tr><td>-</td><td>IV N/S bolus 20ml/kg</td></tr><tr><td>-</td><td>Choice of induction agent and dose  – eg ketamine ~1mg /kg</td></tr><tr><td>-</td><td>Vasopressor/ inotrope with induction – including safe dose</td></tr><tr><td>TV</td><td>90mL</td></tr><tr><td>RR</td><td>at least 20</td></tr><tr><td>FiO2</td><td>100%</td></tr><tr><td>Limit</td><td>at least 35cmH20, not more than ?45cmH20</td></tr></tbody></table></div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":20,"title":"","stemText":"An 18 year old man has been taken to the ED by an ambulance crew. He was found outside a music festival with altered behaviour, after having a seizure. On arrival to the ED his vital signs are:\n\nGCS\nE4 V4 M5 Temperature 39.5 degrees Pulse 120 /min\n\nBP\n135/70 mmHg O2 saturation 99% room air Shortly after arrival, he has another self-limiting seizure. There is no evidence of trauma.","parts":[{"id":"a","label":"Part A","prompt":"List 4 likely differential diagnoses for the cause of this presentation. For each, state the assessment findings (history/examination/investigation) that would confirm its presence and state the management you would institute in the ED. (12 marks) Diagnosis Assessment findings Management Diagnosis Assessment findings Management Diagnosis Assessment findings Management Diagnosis Assessment findings Management"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><thead><tr><th>Cause</th><th>Distinguishing feature</th></tr></thead><tbody><tr><td>Sympathomimetic toxidrome</td><td></td></tr><tr><td>-</td><td>Dilated pupils, Hx use amphetamines, track marks</td></tr><tr><td>-</td><td>Supportive – benzodiazepines, cooling +/- intubation to facilitate paralysis and cooling</td></tr><tr><td>Serotonin toxicity</td><td></td></tr><tr><td>-</td><td>MDMA use, dilated pupils, hypertonia, hyperreflexia, clonus</td></tr><tr><td>-</td><td>As above</td></tr><tr><td>Meningitis</td><td></td></tr><tr><td>-</td><td>Meningism / neck stiffness, petechial rash of DIC, Hx headache / unwell, LP – white cells</td></tr><tr><td>-</td><td>IV antibiotics ceftriaxone 2g +/- vancomycin 30mg/kg, IV fluids, supportive Rx</td></tr><tr><td>Heat stroke</td><td></td></tr><tr><td>-</td><td>Hot environment, use of drugs will predispose, lots of activity (eg dancing)</td></tr><tr><td>-</td><td>Supportive, cooling – cold IV fluids, ice packs, potentially intubation with paralysis</td></tr><tr><td>Status epilepticus</td><td></td></tr><tr><td>-</td><td>Hx epilepsy, Hx of aura prior to seizure</td></tr><tr><td>-</td><td>Anti-epileptic drugs: with dose, supportive care</td></tr><tr><td>Others will be OK</td><td></td></tr></tbody></table></div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":21,"title":"","stemText":"A 21 year old woman has been brought to the ED after an intentional overdose of paracetamol.","parts":[{"id":"a","label":"Part A","prompt":"List 4 key factors of your history that will influence your toxicological risk assessment. (4 marks) 1)________________________________________________________________________________ 2)________________________________________________________________________________ 3)________________________________________________________________________________ 4)________________________________________________________________________________"},{"id":"b","label":"Part B","prompt":"List 3 potential indications for the administration of activated charcoal in this patient. (3 marks) 1)________________________________________________________________________________ 2)________________________________________________________________________________ 3)________________________________________________________________________________ The patient was admitted to your short stay unit overnight to receive an infusion of N-acetylcysteine as management for a high risk ingestion. On your review the following morning, she is looking unwell."},{"id":"c","label":"Part C","prompt":"List 5 criteria that would warrant transfer to a service with liver transplant capabilities. (5 marks) 1)________________________________________________________________________________ 2)________________________________________________________________________________ 3)________________________________________________________________________________ 4)________________________________________________________________________________ 5)________________________________________________________________________________"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">persistent acidosis (pH &lt; 7.3) or arterial lactate &gt; 3 mmol/L</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><tbody><tr><td colspan=\"2\"><strong>2</strong></td></tr><tr><td>-</td><td>Within 2 hrs for immediate release ingestion &gt;200mg/kg</td></tr><tr><td>-</td><td>Within 4 hrs for sustained release &gt;200mg/kg</td></tr><tr><td>-</td><td>Massive (&gt;30g) ingestion – within 4 hours immediate release and all SR</td></tr></tbody></table></div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><tbody><tr><td>•</td><td>INR &gt; 3.0 at 48 hours or &gt; 4.5 at any time</td></tr><tr><td>•</td><td>oliguria or creatinine &gt; 200 mmol/L</td></tr><tr><td>•</td><td>persistent acidosis (pH &lt; 7.3) or arterial lactate &gt; 3 mmol/L</td></tr><tr><td>•</td><td>systolic hypotension with BP &lt;80 mmHg, despite resuscitation</td></tr><tr><td>•</td><td>hypoglycaemia</td></tr><tr><td>•</td><td>severe thrombocytopenia</td></tr><tr><td>•</td><td>encephalopathy of any degree, or ALOC (GCS &lt; 15) in the absence of sedatives.</td></tr></tbody></table></div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":22,"title":"","stemText":"A 16 year old girl has presented with right ear pain.\nA clinical photograph is provided in the PROPS BOOKLET.","parts":[{"id":"a","label":"Part A","prompt":"State 3 relevant findings in the clinical photograph. (3 marks)\n1)________________________________________________________________________________ 2)________________________________________________________________________________ 3)________________________________________________________________________________"},{"id":"b","label":"Part B","prompt":"Give your diagnosis. (1 mark)"},{"id":"c","label":"Part C","prompt":"List 2 bacterial causes of this problem. (2 marks)\n1)________________________________________________________________________________ 2)________________________________________________________________________________"},{"id":"d","label":"Part D","prompt":"List 2 important complications of this condition. (2 marks)\n1)________________________________________________________________________________ 2)________________________________________________________________________________"},{"id":"e","label":"Part E","prompt":"State 3 components of your management of this patient. (3 marks)\n1)________________________________________________________________________________ 2)________________________________________________________________________________ 3)________________________________________________________________________________"}],"propPages":["asset:img7dc2d7cc7252effb40"],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">Pseudomonas aeruginosa</div><div class=\"answer-line\">Staph aureus</div><div class=\"answer-line\"><strong>4</strong></div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">Systemic involvement / sepsis</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">Perichondritis right ear</div></section><section class=\"answer-part\"><h5>Part D</h5><div class=\"answer-line\">Pseudomonas aeruginosa</div><div class=\"answer-line\">Staph aureus</div></section><section class=\"answer-part\"><h5>Part E</h5><div class=\"answer-line\"><strong>4</strong></div><div class=\"answer-line\">Cartilage necrosis</div><div class=\"answer-line\">Abscess formation</div><div class=\"answer-line\">Systemic involvement / sepsis</div><div class=\"answer-line\"><strong>5</strong></div><div class=\"answer-line\">Analgesia – something sensible</div><div class=\"answer-line\">Antibiotics to cover Pseudomonas – eg pip/taz or ciprofloxacin</div><div class=\"answer-line\">ENT review</div><div class=\"answer-line\">Take other ear-rings out</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":23,"title":"","stemText":"A 2 month old boy has been brought to the ED with a fever of 24 hours duration.","parts":[{"id":"a","label":"Part A","prompt":"List 4 examination features that would prompt you to perform a lumbar puncture.\n(4 marks) 1)________________________________________________________________________________ 2)________________________________________________________________________________ 3)________________________________________________________________________________ 4)________________________________________________________________________________"},{"id":"b","label":"Part B","prompt":"List 6 conditions that would need to be met for safe discharge of the child. (6 marks)\n1)________________________________________________________________________________ 2)________________________________________________________________________________ 3)________________________________________________________________________________ 4)________________________________________________________________________________ 5)________________________________________________________________________________ 6)________________________________________________________________________________"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">Apparent neck stiffness</div><div class=\"answer-line\">No other source of fever/ no clear focus is acceptable</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">Organized follow –up within 12-24 hours</div><div class=\"answer-line\">Parents sensible</div><div class=\"answer-line\">Ability to reattend hospital</div><div class=\"answer-line\">Previously healthy</div><div class=\"answer-line\">Looks well</div><div class=\"answer-line\">WBC – 5-15</div><div class=\"answer-line\">Urine clear</div><div class=\"answer-line\">CXR clear</div><div class=\"answer-line\">CSF clear</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":24,"title":"","stemText":"A 50 year old woman has been brought to the ED following a collapse at work. She had complained\n• f a severe headache prior to her collapse.\nA slice from the CT scan of her head is provided in the PROPS BOOKLET.","parts":[{"id":"a","label":"Part A","prompt":"List 5 abnormalities on the image provided. (5 marks)\n1)________________________________________________________________________________ 2)________________________________________________________________________________ 3)________________________________________________________________________________ 4)________________________________________________________________________________ 5)________________________________________________________________________________"},{"id":"b","label":"Part B","prompt":"Give the most likely diagnosis. (1 mark) The patient has been intubated due to a reduced level of consciousness.\nHer vital signs are:\nPulse 115 /min\n\nBP\n200/110 mmHg O2 saturation 90%\n\nFiO2\n0.8 A chest x-ray has been performed. It is provided in the PROPS BOOKLET."},{"id":"c","label":"Part C","prompt":"State the pathology demonstrated. Give 3 supportive features from the chest x-ray. (4 marks) Pathology Supportive features 1)________________________________________________________________________________ 2)________________________________________________________________________________ 3)________________________________________________________________________________"},{"id":"d","label":"Part D","prompt":"State 4 components of your management of this patient. (4 marks)\n1)________________________________________________________________________________ 2)________________________________________________________________________________ 3)________________________________________________________________________________ 4)________________________________________________________________________________"},{"id":"e","label":"Part E","prompt":"List 4 other complications that might occur during this patient’s admission. (4 marks)\n1)________________________________________________________________________________ 2)________________________________________________________________________________ 3)________________________________________________________________________________ 4)________________________________________________________________________________"}],"propPages":["asset:img496b6b0fe8cd31a1e0","asset:img15b9af99eb0be6b450"],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\"><strong>13/18</strong></div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">Subarachnoid blood</div><div class=\"answer-line\">Extension to subdural space on right ie SDH</div><div class=\"answer-line\">Blood in 4th ventricle</div><div class=\"answer-line\">Midline shift to left</div><div class=\"answer-line\">Parafalcine herniation</div><div class=\"answer-line\">Loss grey/white differentiation – oedema</div><div class=\"answer-line\">Also accept comment on localisation of haemorrhage right middle meningeal A territory</div><div class=\"answer-line\"><strong>2</strong></div><div class=\"answer-line\">SAH</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">Non-cardiogenic <strong>pulmonary oedema</strong>:</div><div class=\"answer-line\">Bilateral symmetrical pulmonary infiltrates</div><div class=\"answer-line\">Peri-hilar predominance</div><div class=\"answer-line\">Alveolar in pattern</div><div class=\"answer-line\">Normal heart size</div></section><section class=\"answer-part\"><h5>Part D</h5><div class=\"answer-line\"><strong>Urgent neurosurgical referral </strong></div><div class=\"answer-line\">BP control – eg hydralazine 5mg aliquots aim BP systolic 160mmHg</div><div class=\"answer-line\">Nimodipine infusion to prevent vasospasm</div><div class=\"answer-line\">Increase PEEP to manage APO – eg 10cm H2O</div></section><section class=\"answer-part\"><h5>Part E</h5><div class=\"answer-line\">Vasospasm</div><div class=\"answer-line\">Re-bleed</div><div class=\"answer-line\">Hydrocephalus</div><div class=\"answer-line\">seizure</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":25,"title":"","stemText":"A 3 year old girl has been brought to the ED with a plastic bead stuck in her left nostril.","parts":[{"id":"a","label":"Part A","prompt":"List 3 complications that might occur if the foreign body is not removed in a timely fashion. (3 marks) 1)________________________________________________________________________________ 2)________________________________________________________________________________ 3)________________________________________________________________________________ The child will not sit still for any attempts at removal."},{"id":"b","label":"Part B","prompt":"List 3 options for controlling the patient to facilitate removal. (3 marks)\n1)________________________________________________________________________________ 2)________________________________________________________________________________ 3)________________________________________________________________________________ The patient has been safely immobilised."},{"id":"c","label":"Part C","prompt":"State 5 different techniques for removing the foreign body in the ED. (5 marks)\n1)________________________________________________________________________________ 2)________________________________________________________________________________ 3)________________________________________________________________________________ 4)________________________________________________________________________________ 5)________________________________________________________________________________"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">Suction</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\"><strong>2</strong></div><div class=\"answer-line\">GA in OT</div><div class=\"answer-line\">Procedural sedation in ED eg ketamine</div><div class=\"answer-line\">Physical restraint eg wrap in sheet</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">Suction</div><div class=\"answer-line\">Direct instrumentation eg Curved paperclip</div><div class=\"answer-line\">Foley catheter</div><div class=\"answer-line\">Mouth to mouth from parent</div><div class=\"answer-line\">Attempts at nose blowing with closed opposite nostril</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":26,"title":"","stemText":"A 28 year old woman has been taken to the ED after being found unconscious on the floor of her apartment. She was last seen 24 hours prior. Some of her blood results are provided in the PROPS BOOKLET.","parts":[{"id":"a","label":"Part A","prompt":"State 4 conclusions from the blood results with explanation as to their cause. (4 marks)\n1)________________________________________________________________________________ 2)________________________________________________________________________________ 3)________________________________________________________________________________ 4)________________________________________________________________________________ The patient’s vital signs are:\n\nGCS\nE2 V2 M4 Pulse 100 /min\n\nBP\n130/70 mmHg\n\nRR\n/min O2 saturation 99% 6L via Hudson mask Temperature 37.0 degrees"},{"id":"b","label":"Part B","prompt":"List 4 targeted components of your examination, including the relevance of each.\n(4 marks) 1)________________________________________________________________________________ 2)________________________________________________________________________________ 3)________________________________________________________________________________ 4)________________________________________________________________________________"},{"id":"c","label":"Part C","prompt":"State 5 components of your initial management of this patient. (5 marks)\n1)________________________________________________________________________________ 2)________________________________________________________________________________ 3)________________________________________________________________________________ 4)________________________________________________________________________________ 5)________________________________________________________________________________"}],"propPages":["asset:img4d876f9f487247a11b"],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\"><strong>IV Ca</strong> gluconate 30mL 10% for cardiac protection</div><div class=\"answer-line\">IV HCO3 50-100mmol – K reduction</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">Pupils – looking for toxidromes, or blown pupil of raised ICP</div><div class=\"answer-line\">Focal neuro signs c/w intracranial event</div><div class=\"answer-line\">Muscle compartments – exclude compartment syndrome due to lying on floor</div><div class=\"answer-line\">Skin examination for pressure areas</div><div class=\"answer-line\">Chest / lungs for aspiration from reduced LOC</div><div class=\"answer-line\"><strong>3</strong></div><div class=\"answer-line\"><strong>IV Ca</strong> gluconate 30mL 10% for cardiac protection</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">Also accept – salbutamol for K reduction</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":27,"title":"","stemText":"A 2 year old boy has been brought to the ED after his mother noticed him refusing to bear weight on his right leg.","parts":[{"id":"a","label":"Part A","prompt":"List 5 differential diagnoses. For each, state a key finding on history or examination that would provide supportive evidence. (10 marks) Diagnosis Supportive history / examination findings"},{"id":"b","label":"Part B","prompt":"List 4 investigations that you might perform to establish a diagnosis. Provide justification for each investigation. (8 marks) Investigation Justification"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><thead><tr><th>Item</th><th>Response / justification</th></tr></thead><tbody><tr><td>Fracture eg toddler fracture – tender tibia on palpation shaft, Hx fall</td><td>NAI – multiple bruises different ages, inconsistent Hx from parent</td></tr><tr><td><strong>Septic hip</strong> – fever, pain on passive ROM hip</td><td>Foreign body foot – FB visible on inspection</td></tr></tbody></table></div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><thead><tr><th>Investigation</th><th>Justification</th></tr></thead><tbody><tr><td>CRP / ESR – inflammatory marker elevated in septic hip</td><td>WBC – as above</td></tr></tbody></table></div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false}]);
